import assert from "node:assert/strict";
import { analyzeRainCounter, counterIntervalRows, separateRainEvents, checkRainDoubleMass, calculateArealRainfall, parseRainCsv, parseRainTime, sampleRainPlotRows, rainLimits } from "../assets/js/tools/rainfall-records-tools.js";

// Independent literal/hand expectations. No reference answer is generated by the engine.
let checks = 0;
const eq = (actual, expected, label) => { assert.deepEqual(actual, expected, label); checks++; };
const near = (actual, expected, label) => { assert.ok(typeof actual === "number" && Number.isFinite(actual) && Math.abs(actual - expected) <= Math.max(1e-12, Math.abs(expected) * 1e-10), `${label}: ${actual} vs ${expected}`); checks++; };
const bad = (fn, label) => { assert.throws(fn, Error, label); checks++; };
const timed = (header, values, minutes = 60) => `time,${header}\n` + values.map((v, i) => `${new Date(Date.UTC(2024, 0, 1, 0, i * minutes)).toISOString().slice(0, 16).replace("T", " ")},${v}`).join("\n");
const counter = (values, options = {}) => analyzeRainCounter({ csv: timed("counter", values), stepMinutes: 60, unit: "mm", ...options });
const events = (values, options = {}) => separateRainEvents({ csv: timed("rainfall", values), stepMinutes: 60, dryGapMinutes: 120, unit: "mm", ...options });
const massCsv = "period,target,reference\nP1,10,10\nP2,20,20\nP3,30,30\nP4,15,10\nP5,30,20\nP6,45,30";
const mass = (options = {}) => checkRainDoubleMass({ csv: massCsv, splitAfter: 3, unit: "mm", ...options });
const weightsCsv = "station,weightPercent\nA,20\nB,30\nC,50";
const arealCsv = "period,A,B,C\nP1,10,20,30\nP2,0,0,0\nP3,NA,5,NA";
const area = (options = {}) => calculateArealRainfall({ weightsCsv, csv: arealCsv, unit: "mm", ...options });

// CSV grammar and precision.
eq(parseRainCsv("\uFEFFa,b\r\n 1 , 2 \r\n", ["a", "b"]).rows, [["1", "2"]], "BOM, CRLF and cell whitespace");
eq(parseRainCsv("a,b\n0,NA\n1,", ["a", "b"]).rows, [["0", "NA"], ["1", ""]], "missing cells preserved as strings");
for (const text of ["", "a,b", "a,a\n1,2", ",b\n1,2", "a,b\n1", "a,b\n1,2,3", 'a,b\n"1",2', "a,b\n1,2\n\n3,4", "a,b\n1,2\n   "]) bad(() => parseRainCsv(text), "malformed CSV rejected");
bad(() => parseRainCsv("b,a\n1,2", ["a", "b"]), "ordered exact header");
bad(() => parseRainCsv("a\n" + "x\n".repeat(rainLimits.rows + 1)), "row cap");
bad(() => parseRainCsv("a\n" + "x".repeat(rainLimits.bytes)), "byte cap");
bad(() => parseRainCsv(Array.from({ length: 32 }, (_, i) => `H${i}`).join(",") + "\n" + "1,".repeat(31) + "1"), "column cap");
bad(() => parseRainCsv("a,b,c,d,e\n" + "1,2,3,4,5\n".repeat(80001)), "cell cap below row cap");
for (const value of ["-1", "NaN", "Infinity", "-999", "<0.1", "0x10", "1oops", "1e309", "1e-400", "1e-13"]) bad(() => counter([0, value]), `reject unsupported value ${value}`);
near(counter([0, "1e-12"]).acceptedMm, 1e-12, "supported tiny positive");
near(counter([0, "1e9"]).acceptedMm, 1e9, "supported large positive");
bad(() => counter([0, "1000000001"]), "upper bound");
bad(() => counter([0, 1], { unit: "cm" }), "unsupported unit");

// Calendar/time semantics, independent expected epoch difference.
near(parseRainTime("2024-03-01 00:00") - parseRainTime("2024-02-28 00:00"), 2880, "leap February contains two days");
for (const t of ["2023-02-29 00:00", "2024-04-31 00:00", "2024-00-01 00:00", "2024-13-01 00:00", "2024-01-00 00:00", "2024-01-01 24:00", "2024-01-01 00:60", "2024-01-01T00:00Z", "01/02/2024 00:00", "0999-01-01 00:00"]) bad(() => parseRainTime(t), `invalid clock ${t}`);
for (const step of [0, -1, 1.5, 1441, Number.NaN, Number.POSITIVE_INFINITY, "60"]) bad(() => counter([0, 1], { stepMinutes: step }), "invalid expected step");
for (const later of ["2024-01-01 00:00", "2023-12-31 23:00", "2024-01-01 01:30"]) bad(() => counter([], { csv: `time,counter\n2024-01-01 00:00,0\n${later},1` }), "duplicate, descending or non-grid");
near(counter([], { csv: "time,counter\n2024-01-01 00:00,0\n2024-01-01 00:01,2", stepMinutes: 1 }).acceptedMm, 2, "one-minute lower step boundary");
near(counter([], { csv: "time,counter\n2024-01-01 00:00,0\n2024-01-02 00:00,2", stepMinutes: 1440 }).acceptedMm, 2, "one-day upper step boundary");

// Counter: sum accepted pairs, never infer an increment at reset/gap.
let c = counter([0, 1, 3, 0, 2]);
near(c.acceptedMm, 5, "counter manual accepted sum 1+2+2");
eq([c.valid, c.validMinutes, c.excludedMinutes, c.partial], [3, 180, 60, true], "counter coverage");
eq(c.rows.map(x => x.rainfallMm), [1, 2, null, 2], "reset interval unknown, later pair recovers");
eq(c.rows.map(x => x.rawDeltaMm), [1, 2, -3, 2], "raw negative retained");
near(counter([100, 101]).acceptedMm, 1, "first counter is only baseline");
near(counter([7, 7, 7]).acceptedMm, 0, "measured zero delta");
eq(counter(["NA", 1, 2]).rows.map(x => x.rainfallMm), [null, 1], "missing prior endpoint");
eq(counter([0, "", 2, 3]).rows.map(x => x.rainfallMm), [null, null, 1], "blank not zero, both adjacent pairs unknown");
eq(counter(["NA", "NA"]).acceptedMm, null, "no valid increment is not measured zero");
c = counter([], { csv: "time,counter\n2024-01-01 00:00,1\n2024-01-01 02:00,5\n2024-01-01 03:00,6" });
eq(c.rows.map(x => x.rainfallMm), [null, 1], "gap delta not distributed");
near(c.rows[0].rawDeltaMm, 4, "unallocated gap delta retained");
eq([c.validMinutes, c.excludedMinutes], [60, 120], "gap time coverage");
bad(() => counter([1]), "baseline alone insufficient");
near(counter([0, 1, 3, 0, 2].map(x => x / 25.4), { unit: "in" }).acceptedMm, 5, "counter independent inch conversion");
bad(() => counter(["0.000000000001", "0.0000000000010001"]), "unrepresentably small transferable increment is rejected, not rounded to zero");
c = counter([], { csv: "time,counter\n2024-01-01 00:00,0\n2024-01-01 04:00,1\n2024-01-01 05:00,2" });
eq([c.valid, c.expectedIntervals, c.validMinutes, c.excludedMinutes], [1, 5, 60, 240], "expected interval denominator includes every skipped step");
eq(counterIntervalRows(c, 60), [{ time: "2024-01-01 01:00", rainfallMm: null }, { time: "2024-01-01 04:00", rainfallMm: null }, { time: "2024-01-01 05:00", rainfallMm: 1 }], "initial unknown anchor preserves original transfer window without filling rainfall");
const initialGapEvents = separateRainEvents({ csv: "time,rainfall\n2024-01-01 01:00,NA\n2024-01-01 04:00,NA\n2024-01-01 05:00,1", stepMinutes: 60, dryGapMinutes: 120, unit: "mm" });
eq([initialGapEvents.valid, initialGapEvents.expectedIntervals, initialGapEvents.observedMm], [1, 5, 1], "transfer coverage remains1/5, not1/2");
const largeCounter = analyzeRainCounter({ csv: timed("counter", Array.from({ length: 100000 }, (_, i) => i), 1), stepMinutes: 1, unit: "mm" });
eq([largeCounter.sourceRows, largeCounter.rows.length, largeCounter.valid], [100000, 99999, 99999], "supported100,000-row record is fully analyzed");
near(largeCounter.acceptedMm, 99999, "large valid record manual telescoping sum");

// Events: literal interval-end record; no inter-event wall-clock shortcut.
const sample = [0, 0, 2, 1, 0, 0, 4, 0, 0];
let e = events(sample);
eq([e.events.length, e.bounded, e.valid, e.missing, e.skipped], [2, 2, 9, 0, 0], "two exactly separated bounded events");
eq(e.events.map(x => x.depthMm), [3, 4], "event depth manual sums");
eq(e.events.map(x => x.duration), [120, 60], "end-stamped wet duration");
eq(e.events.map(x => x.meanMmHour), [1.5, 4], "event mean interval duration basis");
eq(e.events.map(x => x.peakMmHour), [2, 4], "peak interval not instantaneous intensity");
eq([e.events[0].startTime, e.events[0].endTime], ["2024-01-01 01:00", "2024-01-01 03:00"], "interval-end event boundaries");
near(e.observedMm, 7, "observed depth conservation");
e = events(sample, { dryGapMinutes: 180 });
eq([e.events.length, e.events[0].duration, e.events[0].leftUnknown, e.events[0].rightUnknown], [1, 300, true, true], "larger gap joins, including internal dry time, context insufficient");
near(e.events[0].meanMmHour, 1.4, "joined mean 7/5 hours");
e = events([0, 0, 1, 0, 2, 0, 0]);
eq([e.events.length, e.events[0].duration, e.bounded], [1, 180, 1], "one dry interval insufficient to split");
e = events([1, "NA", 2, 0, 0]);
eq(e.events.map(x => [x.leftUnknown, x.rightUnknown]), [[true, true], [true, false]], "NA censors both sides, later dry context closes");
eq([e.observedMm, e.missing, e.bounded], [3, 1, 0], "missing does not become dry");
e = events([], { csv: "time,rainfall\n2024-01-01 00:00,1\n2024-01-01 02:00,2\n2024-01-01 03:00,0\n2024-01-01 04:00,0" });
eq([e.skipped, e.expectedIntervals, e.events.length], [1, 5, 2], "implicit gap creates fragments, not inferred zero");
eq(e.events.map(x => [x.leftUnknown, x.rightUnknown]), [[true, true], [true, false]], "gap boundaries explicit");
e = events([1, "NA", 0, 0, 2, 0, 0]);
eq([e.events[1].leftUnknown, e.events[1].rightUnknown], [false, false], "known dry duration reestablishes boundaries after missing");
eq([events([0, 0, 0]).events.length, events([0, 0, 0]).observedMm], [0, 0], "all dry is valid zero");
eq([events(["NA", "", "NA"]).events.length, events(["NA", "", "NA"]).observedMm], [0, null], "all missing is not dry zero");
eq(events([1]).events.map(x => [x.leftUnknown, x.rightUnknown]), [[true, true]], "single wet interval both edges unknown");
near(events([0, 0, 1e-12, 0, 0]).observedMm, 1e-12, "no positive trace erased");
near(events(sample.map(x => x / 25.4), { unit: "in" }).observedMm, 7, "event inch equivalence");
for (const gap of [0, 59, -1, 10081, 120.5, Number.NaN, Infinity]) bad(() => events(sample, { dryGapMinutes: gap }), "invalid chosen dry gap");
eq(events(sample, { dryGapMinutes: 119 }).events.length, 2, "nonmultiple gap has interval-resolution comparison");
eq(events(sample, { dryGapMinutes: 121 }).events.length, 1, "one minute above dry run does not split");

// Double mass: original-row split, common-pair accumulation, no auto correction.
let m = mass();
eq([m.targetMm, m.referenceMm, m.paired, m.excluded], [150, 120, 6, 0], "paired totals manual");
eq(m.segments.map(s => s.ratio), [1, 1.5], "segment increment ratios");
near(m.relativeChange, 50, "relative ratio change, not correction factor");
eq(m.rows.map(r => [r.cumulativeReferenceMm, r.cumulativeTargetMm]), [[10, 10], [30, 30], [60, 60], [70, 75], [90, 105], [120, 150]], "manual cumulative pairs");
m = mass({ csv: massCsv.replace("P2,20,20", "P2,NA,20") });
eq([m.targetMm, m.referenceMm, m.paired, m.excluded], [130, 100, 5, 1], "omit both members of incomplete pair");
eq(m.segments.map(s => s.count), [2, 3], "split stays at original row3");
near(m.relativeChange, 50, "paired omission retains ratios");
m = mass({ csv: massCsv.replace("P1,10,10", "P1,10,NA").replace("P2,20,20", "P2,,20") });
eq([m.segments[0].ratio, m.relativeChange], [null, null], "insufficient usable segment pairs not assessed");
m = mass({ csv: "period,target,reference\nA,1,0\nB,2,0\nC,1,1\nD,2,2", splitAfter: 2 });
eq([m.segments[0].ratio, m.relativeChange], [null, null], "zero reference undefined");
m = mass({ csv: "period,target,reference\nA,0,1\nB,0,2\nC,1,1\nD,2,2", splitAfter: 2 });
eq([m.segments[0].ratio, m.relativeChange], [0, null], "zero early ratio has no relative change");
m = mass({ csv: "period,target,reference\nA,0,0\nB,0,0\nC,0,0\nD,0,0", splitAfter: 2 });
eq([m.paired, m.segments[0].ratio, m.segments[1].ratio, m.relativeChange], [4, null, null, null], "observed dry pairs retained without fabricated ratio");
for (const split of [1, 5, 3.5, NaN]) bad(() => mass({ splitAfter: split }), "invalid original-row split");
for (const replacement of ["P1,20,20", "=bad,20,20", "@bad,20,20", "<script>,20,20"]) bad(() => mass({ csv: massCsv.replace("P2,20,20", replacement) }), "duplicate/unsafe period");
m = mass({ unit: "in" });
near(m.targetMm, 3810, "150 inches =3810 mm");
near(m.relativeChange, 50, "unit-invariant segment change");

// Areal: fixed geometry, complete periods only, never normalize available gauges.
let a = area();
eq([a.complete, a.incomplete, a.empty], [2, 1, 0], "network period counts");
near(a.rows[0].meanMm, 23, "0.2*10+0.3*20+0.5*30");
near(a.rows[1].meanMm, 0, "observed all-zero network period");
eq(a.rows[2].meanMm, null, "no full mean for incomplete network");
near(a.rows[2].coveragePercent, 30, "only B's fixed weight observed");
near(a.rows[2].contributionMm, 1.5, "known contribution, not 5 mm renormalized mean");
eq(a.rows[2].missingStations, ["A", "C"], "missing stations named");
a = area({ csv: "period,C,A,B\nP1,30,10,20" });
near(a.rows[0].meanMm, 23, "columns matched by ID, not positions");
a = area({ csv: "period,A,B,C\nP1,NA,,NA" });
eq([a.empty, a.rows[0].meanMm, a.rows[0].contributionMm, a.rows[0].coveragePercent], [1, null, null, 0], "all absent is not measured zero");
a = area({ weightsCsv: "station,weightPercent\nA,0.00000001\nB,99.99999999", csv: "period,A,B\nP1,NA,10" });
eq(a.rows[0].complete, false, "missing tiny-weight station cannot round into completeness");
eq(a.rows[0].meanMm, null, "coverage rounding never authorizes mean");
a = area({ weightsCsv: "station,weightPercent\nA,20\nB,30\nC,50.0000001" });
near(a.rows[0].meanMm, (200 + 600 + 1500.000003) / 100.0000001, "only sub-tolerance rounding normalized");
for (const w of ["station,weightPercent\nA,20\nB,30", "station,weightPercent\nA,0\nB,100", "station,weightPercent\nA,-1\nB,101", "station,weightPercent\nA,NA\nB,100", "station,weightPercent\nA,50\nA,50", "station,weightPercent\n=bad,50\nB,50", "station,weightPercent\nA,100"]) bad(() => area({ weightsCsv: w }), "invalid or incomplete weight network");
for (const csv of ["period,A,B,D\nP1,1,2,3", "period,A,B\nP1,1,2", "period,A,A\nP1,1,2", "period,A,B,C\nP1,1,2,3\nP1,4,5,6", "period,A,B,C\nP1,1,-1,3"]) bad(() => area({ csv }), "invalid network observations");
const manyWeights = "station,weightPercent\n" + Array.from({ length: 30 }, (_, i) => `S${i + 1},${100 / 30}`).join("\n");
const manyData = "period," + Array.from({ length: 30 }, (_, i) => `S${i + 1}`).join(",") + "\nP1," + Array(30).fill(10).join(",");
near(area({ weightsCsv: manyWeights, csv: manyData }).rows[0].meanMm, 10, "30-station upper bound with rounding");
bad(() => area({ weightsCsv: manyWeights + "\nExtra,1", csv: manyData }), "31 stations rejected");
near(area({ unit: "in" }).rows[0].meanMm, 584.2, "23 inches =584.2 mm");
near(area({ csv: "period,A,B,C\nP1,0.000000001,0.000000001,0.000000001" }).rows[0].meanMm, 1e-9, "small positive weighted depth");
near(area({ csv: "period,A,B,C\nP1,1000000000,1000000000,1000000000" }).rows[0].meanMm, 1e9, "large finite weighted depth");
const longCsv = "period,A,B,C\n" + Array.from({ length: 125 }, (_, i) => `P${i + 1},10,20,30`).join("\n");
a = area({ csv: longCsv });
eq([a.sourceRows, a.rows.length, a.complete], [125, 125, 125], "all rows calculated beyond UI preview");
near(a.rows[124].meanMm, 23, "last non-preview row retained");

const fiveHundred = Array.from({ length: 500 }, (_, i) => i);
eq(sampleRainPlotRows(fiveHundred), fiveHundred, "exactly500 observations are not thinned while claiming all points");
const thinned = sampleRainPlotRows(Array.from({ length: 501 }, (_, i) => i));
eq([thinned.length, thinned[0], thinned.at(-1)], [500, 0, 500], "over-cap plot retains exactly500 original points and both endpoints");
eq(new Set(thinned).size, 500, "no duplicated or interpolated plot points");
eq(sampleRainPlotRows([]), [], "empty plot stays empty");
console.log(`Rainfall records verification passed: ${checks} independent numeric, calendar, missing-data, boundary, unit, plot and strict-parser assertions.`);
